"```java
@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

    private static final String BASE_URL = "/api/admin/mensagens/";
    private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
    private final BridgeFaker faker = new BridgeFaker();

    @Autowired
    private InstituicaoFactory instituicaoFactory;

    @Autowired
    private DAO dao;

    @Autowired
    private LDAPJwtFactory ldapJwtFactory;

    @Test
    @DisplayName("Deve retornar 401 ao tentar criar mensagem sem autenticação")
    void storeMensagemExpectUnauthorized() {
        given()
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(401);
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para todos os estudantes")
    void storeMensagemAtivaParaTodosExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2); // ATIVA
            m.instituicaoIds.set(Collections.emptyList());
            m.dataValidade.set(this.faker.date().future(10, DAYS).toInstant());
            m.descricao.set("<p>Esta é uma mensagem com <strong>tags HTML</strong>.</p>");
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var qMensagem = QMensagem.mensagem;
        var storedMensagem = this.dao.queryFactory()
                .selectFrom(qMensagem)
                .where(qMensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());

        var qMensagemInstituicao = QMensagemInstituicao.mensagemInstituicao;
        var countInstituicoes = this.dao.queryFactory()
                .select(qMensagemInstituicao.count())
                .from(qMensagemInstituicao)
                .where(qMensagemInstituicao.mensagem.id.eq(storedMensagemId))
                .fetchOne();
        assertThat(countInstituicoes).isZero();
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para instituições específicas")
    void storeMensagemAtivaParaInstituicoesExpectSuccess() {
        var instituicoes = this.instituicaoFactory.createRandom(3);
        var instituicaoIds = instituicoes.stream().map(Instituicao::getId).toList();

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(2); // ATIVA
            m.instituicaoIds.set(instituicaoIds);
            m.dataValidade.set(this.faker.date().future(5, DAYS).toInstant());
        });

        var givenRequest = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .formParam("dataValidade", mensagemInputDto.getDataValidade().toString());

        instituicaoIds.forEach(id -> givenRequest.formParam("instituicaoIds", id));

        var storedMensagemId = givenRequest
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var qMensagem = QMensagem.mensagem;
        var storedMensagem = this.dao.queryFactory()
                .selectFrom(qMensagem)
                .where(qMensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());

        var qMensagemInstituicao = QMensagemInstituicao.mensagemInstituicao;
        var storedInstituicaoIds = this.dao.queryFactory()
                .select(qMensagemInstituicao.instituicao.id)
                .from(qMensagemInstituicao)
                .where(qMensagemInstituicao.mensagem.id.eq(storedMensagemId))
                .fetch();

        assertThat(storedInstituicaoIds).containsExactlyInAnyOrderElementsOf(instituicaoIds);
    }

    @Test
    @DisplayName("Deve criar mensagem inativa")
    void storeMensagemInativaExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
            m.situacaoMensagem.set(1); // INATIVA
            m.instituicaoIds.set(Collections.emptyList());
            m.dataValidade.set(null);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(MULTIPART_FORM_DATA_VALUE)
                .formParam("titulo", mensagemInputDto.getTitulo())
                .formParam("descricao", mensagemInputDto.getDescricao())
                .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var qMensagem = QMensagem.mensagem;
        var storedMensagem = this.dao.queryFactory()
                .selectFrom(qMensagem)
                .where(qMensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(1);
        assertThat(storedMensagem.getDataValidade()).isNull();

        var qMensagemInstituicao = QMensagemInstituicao.mensagemInstituicao;
        var countInstituicoes = this.dao.queryFactory()
                .select(qMensagemInstituicao.count())
                .from(qMensagemInstituicao)
                .where(qMensagemInstituicao.mensagem.id.eq(storedMensagemId))
                .fetchOne();
        assertThat(countInstituicoes).isZero();
    }
}
