"```java
@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

 private static final String BASE_URL = "/api/admin/mensagens/";
 private static final Integer SITUACAO_INATIVA = 1;
 private static final Integer SITUACAO_ATIVA = 2;

 private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
 private final BridgeFaker faker = new BridgeFaker();

 @Autowired
 private MensagemFactory mensagemFactory;

 @Autowired
 private InstituicaoFactory instituicaoFactory;

 @Autowired
 private DAO dao;

 @Autowired
 private LDAPJwtFactory ldapJwtFactory;

 @Test
 @DisplayName("Deve atualizar mensagem para ativa para todos os estudantes")
 void updateMensagemToAtivaForAllStudentsExpectSuccess() {
  var mensagemInDb = this.mensagemFactory.createRandom();
  var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
   m.titulo.set(this.faker.lorem().sentence());
   m.descricao.set("<p>Descrição com <b>HTML</b> e um link.</p>");
   m.situacaoMensagem.set(SITUACAO_ATIVA);
   m.instituicaoIds.set(Collections.emptyList());
   m.dataValidade.set(this.faker.date().future(10, DAYS).toInstant());
  });

  given()
   .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
   .contentType(MULTIPART_FORM_DATA_VALUE)
   .formParam("titulo", mensagemInputDto.getTitulo())
   .formParam("descricao", mensagemInputDto.getDescricao())
   .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
   .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
   .formParam("instituicaoIds", mensagemInputDto.getInstituicaoIds())
   .when()
   .put(BASE_URL + mensagemInDb.getId())
   .then()
   .statusCode(200);

  var updatedMensagem = this.dao.find(Mensagem.class, mensagemInDb.getId());
  var updatedInstituicoes = this.dao.list(MensagemInstituicao.class, "mensagem.id", updatedMensagem.getId());

  assertThat(updatedMensagem).isNotNull();
  assertThat(updatedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
  assertThat(updatedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
  assertThat(updatedMensagem.getSituacaoMensagem()).isEqualTo(SITUACAO_ATIVA);
  assertThat(updatedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
  assertThat(updatedInstituicoes).isEmpty();
 }

 @Test
 @DisplayName("Deve atualizar mensagem para ativa para instituições específicas")
 void updateMensagemToAtivaForSpecificInstituicoesExpectSuccess() {
  var instituicoes = this.instituicaoFactory.createRandom(3);
  var instituicaoIds = instituicoes.stream().map(Instituicao::getId).toList();
  var mensagemInDb = this.mensagemFactory.createRandom();

  var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
   m.titulo.set(this.faker.lorem().sentence());
   m.descricao.set("<p>Nova descrição da mensagem.</p>");
   m.situacaoMensagem.set(SITUACAO_ATIVA);
   m.instituicaoIds.set(instituicaoIds);
   m.dataValidade.set(this.faker.date().future(5, DAYS).toInstant());
  });

  given()
   .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
   .contentType(MULTIPART_FORM_DATA_VALUE)
   .formParam("titulo", mensagemInputDto.getTitulo())
   .formParam("descricao", mensagemInputDto.getDescricao())
   .formParam("situacaoMensagem", mensagemInputDto.getSituacaoMensagem())
   .formParam("dataValidade", mensagemInputDto.getDataValidade().toString())
   .formParam("instituicaoIds", mensagemInputDto.getInstituicaoIds())
   .when()
   .put(BASE_URL + mensagemInDb.getId())
   .then()
   .statusCode(200);

  var updatedMensagem = this.dao.find(Mensagem.class, mensagemInDb.getId());
  var updatedMensagemInstituicoes = this.dao.list(MensagemInstituicao.class, "mensagem.id", updatedMensagem.getId());
  var updatedInstituicaoIds = updatedMensagemInstituicoes.stream()
   .map(mi -> mi.getInstituicao().getId())
   .toList();

  assertThat(updatedMensagem).isNotNull();
  assertThat(updatedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
  assertThat(updatedMensagem.getSituacaoMensagem()).isEqualTo(SITUACAO_ATIVA);
  assertThat(updatedInstituicaoIds).containsExactlyInAnyOrderElementsOf(instituicaoIds);
 }

 @Test
 @DisplayName("Deve atualizar mensagem para inativa limpando data e instituições")
 void updateMensagemToInativaExpectSuccess() {
  var mensagemInDb = this.mensagemFactory.create(m -> {
   m.situacaoMensagem.set(SITUACAO_ATIVA);
   m.dataValidade.set(Instant.now().plus(1, ChronoUnit.DAYS));
  });

  var mensagemInputDto = this.mensagemInputITDtoFactory.create(m -> {
   m.titulo.set(this.faker.lorem().sentence());
   m.descricao.set("Descrição de mensagem inativa.");
